CASES = [
 dict(key='home-bedroom', old='Reference2Scene-PinkAccentLivingRoom', slug='Reference2Scene-TimberBedroom', category='Reference2Scene', title='木框卧室与书桌角', difficulty='easy',
 en='Reconstruct the bedroom in input/reference.png. Include the timber bed frame and footboard, layered bedding and pillows, bedside drawer unit, tall wardrobe, desk and blue chair, curtained window and wall recesses. Preserve the open floor around the bed and the furniture depth ordering. Model drawer divisions, handles, bed legs and chair supports as editable three-dimensional details. Give bedding thickness and soft edges. Match the pale walls, warm timber, gray fabric and diffuse interior lighting. Use a mattress width of 1.6 m as a modelling convention; infer other dimensions from the image.',
 zh='根据 input/reference.png 重建卧室，包括木框床与床尾板、分层床品及枕头、床头抽屉柜、高衣柜、书桌与蓝椅、带帘窗户及墙面凹处。保留床周围空地和家具前后层次。抽屉分格、把手、床腿和椅子支撑需有可编辑三维细节，床品具有厚度与柔边。匹配浅墙、暖木、灰布料及柔和室内光。以床垫宽 1.6 m 作为建模约定，其余尺寸按图推断。', features='床框床品；柜体分格；书桌椅；窗帘；家具间净空'),
 dict(key='home-kitchen', old='Reference2Scene-TwinBasinBathroom', slug='Reference2Scene-IslandKitchen', category='Reference2Scene', title='环绕橱柜与中央岛台', difficulty='medium',
 en='Reconstruct the kitchen in input/reference.png. Build the perimeter base and wall cabinets, central island, tiled backsplash, inset sink and curved tap, cooker and extractor hood, refrigerator, and pair of hanging lamps. Preserve cabinet divisions and handles, the appliance recesses, the island clearance and the relative heights of worktops and wall units. The sink must have a real cavity, cabinet doors need thickness, and the lamp shades need open undersides. Match the dark timber, pale worktops, reflective appliances and warm ceiling light. Set the main worktop height to 0.90 m as a scale convention.',
 zh='根据 input/reference.png 重建厨房，包括周边地柜及吊柜、中央岛台、瓷砖背墙、嵌入水槽与弯龙头、灶具及烟机、冰箱和两盏吊灯。保留柜门分格与把手、设备凹位、岛台周围净空，以及台面与吊柜的高度关系。水槽需有真实凹腔，柜门具有厚度，灯罩底部开口。匹配深木色、浅台面、反光家电及温暖顶光。以主台面高 0.90 m 作为尺度约定。', features='环绕橱柜；岛台通道；水槽龙头；烟机灶具；冰箱；吊灯'),
 dict(key='3d-city', old='Reference2Scene-StripedDiningRoom', slug='Reference2Scene-CityBlocks', category='Reference2Scene', title='城市街区与道路网络', difficulty='medium',
 en='Reconstruct the city diorama in input/reference.png. Preserve the arrangement of building blocks, street intersections, pavements, planted areas and variations in roof height. Model distinct facade openings, projecting balconies or ledges where visible, recessed entrances, roof equipment and street-level gaps. Keep streets continuous through intersections and separate pavement from carriageway. Match the reference isometric composition, compact proportions and muted colors. Use an orthographic main camera. Use a typical storey height of 3 m as a scale convention; do not treat image-derived dimensions as surveyed measurements. Tiny signs and window interiors may be simplified.',
 zh='根据 input/reference.png 重建城市微缩场景，保留建筑街块、交叉路口、人行道、绿化和屋顶高低变化的排列。可见立面开口、外挑阳台或檐板、凹入入口、屋顶设施及沿街间隙需有形体。道路在交叉口连续，人行道与车行道区分。匹配等轴构图、紧凑比例和低饱和配色，主相机使用正交投影。以典型楼层高 3 m 作为尺度约定，不将推断尺寸当作测量值；细小标牌及窗内细节可简化。', features='多街块布局；交叉路口；建筑高度层次；立面开口；人行道与绿化'),
 dict(key='pawn-shop', old='Reference2Scene-StylizedTramStation', slug='Reference2Scene-AntiqueShop', category='Reference2Scene', title='砖拱旧货店与密集陈列', difficulty='hard',
 en='Reconstruct the antique shop in input/reference.png. Build the timber floor and beams, brick columns and archway, tall open display shelving, rear cabinetry, wall pictures and clocks, rugs, barrels and boxes, lamps, pots, vessels and busts. Preserve the foreground shelving occlusion, central route through the arch and the deeper adjoining room. Shelves need open gaps and real thickness; arches need curved openings and masonry depth. Use varied genuine three-dimensional objects to recover the dense but grouped display, rather than flat textures of clutter. Match warm light, worn timber and the contrast between the bright rear room and darker foreground. Set the arch opening height to 2.4 m as a scale convention. Small labels and picture subjects may be simplified.',
 zh='根据 input/reference.png 重建旧货店，包括木地板与梁、砖柱及拱门、高开放陈列架、后排柜体、壁画与钟、地毯、桶箱、灯具、盆罐和胸像。保持前景货架遮挡、穿过拱门的中央通路，以及相邻房间纵深。货架保留开口与厚度，砖拱具有弧形开口和墙体深度。用多种真实三维物体表现密集但成组的陈列，不能用杂物照片贴图替代。匹配暖光、旧木和后方明亮房间与暗前景的对比。以拱门净高 2.4 m 作为尺度约定；小标签和画面内容可简化。', features='砖拱梁柱；前后房间；开放陈列架；器皿杂物分组；暖光与遮挡'),
 dict(key='voxel-atolls', old='Reference2Scene-FantasyForest', slug='Reference2Scene-WinterAtolls', category='Reference2Scene', title='积雪浮岛与绳索步道', difficulty='hard',
 en='Reconstruct the voxel landscape in input/reference.png. Preserve the large-scale distribution of stepped snow-covered islands, vertical cliff faces, open water or void between islands, winding pale paths, rope fences, small buildings, bare trees and grouped vegetation. Keep the height hierarchy and connected paths; make fence posts, horizontal ropes, roofs and protruding branches into genuine geometry. Retain the blocky silhouette and restrained snow, stone, wood and green palette without smoothing everything into rounded hills. Use an orthographic main camera and a typical small doorway height of 2 m as a scale convention. Individual grass blades may be simplified, but their spatial clusters and the clear areas around paths must remain.',
 zh='根据 input/reference.png 重建体素地景，保留阶梯积雪岛块、垂直崖面、岛间水面或空隙、蜿蜒浅色步道、绳索围栏、小屋、枯树及成组植被的整体分布。保持高差层级和路径连通，围栏柱、横绳、屋顶及伸出枝干使用真实几何。保留方块轮廓和克制的雪、岩、木、绿色调，不将所有形体磨成圆山。使用正交主相机，以典型小门洞高 2 m 作为尺度约定。单根草叶可简化，但植被分组和路旁空地应保留。', features='多层浮岛；阶梯崖壁；步道连接；绳索围栏；小屋枯树；植被分区'),
 dict(key='canyon', old='Brief2Scene-RockyMountainBasin', slug='Brief2Scene-SandstonePass', category='Brief2Scene', title='砂岩峡谷通道与荒漠植被', difficulty='medium',
 en='Create a stylized sandstone canyon approximately 60 m long and 36 m wide. A dry winding passage, at least 3 m wide, must connect the foreground entrance to an opening at the far end. Flank it with irregular terraced rock masses 8–18 m high, including at least two freestanding pillars, a natural arch with an open span of at least 6 m and scattered broken slabs. Use layered and fractured rock shapes rather than uniformly scaled cubes. Place three separated vegetation clusters with fan palms, branching cacti and low dry grasses on soil pockets, leaving the passage clear. Keep roots grounded and avoid floating rocks or impossible arch support. Use warm orange sandstone, pale dusty ground and restrained green plants, with afternoon side light that separates foreground rocks from the distant ridge. Use metres and Z up. Render a perspective main view from the passage entrance at eye height 1.7 m and a second elevated view at least 8 m above ground showing the route and arch. Render 960 by 640 pixels using Cycles, AgX, exposure 0 and gamma 1. No reference image or starting scene is supplied; the layout is yours to design.',
 zh='建立长约 60 m、宽约 36 m 的卡通砂岩峡谷。干燥蜿蜒通道从前景入口贯通至远端出口，净宽至少 3 m。两側布置高 8–18 m 的不规则层状岩体，包括至少两根独立石柱、一座净跨至少 6 m 的天然岩拱和散落碎岩板。岩体呈层理和断裂形态，不能只将立方体均匀缩放。三处相互分离的土壤区域种植扇叶棕榈、分枝仙人掌和低矮枯草，保持通路畅通。根部落地，避免悬浮岩块或不合理岩拱支撑。采用暖橙砂岩、浅尘土地和克制绿植，以午后侧光区分前景岩石和远山。米制、Z 向上；主透视相机位于通道入口、眼高 1.7 m，第二视角位于离地至少 8 m 的高处，能看清路线与岩拱。使用 Cycles、AgX、曝光 0、gamma 1 渲染 960×640。不给参考图或初始场景，自行设计布局。', features='贯通通道；层理岩壁；独立石柱；天然岩拱；荒漠植被三组；高低双视角'),
 dict(key='attic-hideout', old='SceneEdit-KitchenKettle', slug='SceneEdit-AtticTelescope', category='SceneEdit', title='阁楼工作室：补回望远镜', difficulty='medium', mode='geometry', remove=['Cylinder.005'],
 en='The telescope and its supporting tripod have been removed from the right side of this attic. Restore the assembly shown in input/reference.png: the long tilted optical tube, larger front rim, eyepiece end, mounting joint and slender three-legged support. Use the surviving furniture and wall to determine its size and position. The tube must connect to the mount, the mount to the tripod, and the feet must rest on the floor. Match the dark finish and narrow silhouette. Do not alter the desk, monitors, stool, posters, globe, walls, lighting or other surviving objects.',
 zh='阁楼右侧的望远镜及三脚支架已被移除。按 input/reference.png 补回长倾斜镜筒、较大的前端口沿、目镜端、安装关节和细三脚支撑，利用保留家具及墙面判断大小与位置。镜筒连接安装座，安装座连接三脚架，支脚落地。匹配深色表面和细长轮廓。不改书桌、显示器、凳子、海报、地球仪、墙面、照明及其他保留物体。', features='倾斜镜筒；镜口与目镜；安装关节；三脚架；落地与局部保持性'),
 dict(key='medieval-blacksmith', old='SceneEdit-StreetBollards', slug='SceneEdit-BlacksmithForge', category='SceneEdit', title='铁匠铺：恢复炉台与锻造设备', difficulty='medium', mode='geometry', remove=['Forge','Bellow','Anvil','AnvilBolts','AnvilStand','IronHotEdge1','IronHotEdge2'],
 en='The forge, bellows and anvil assembly beneath the side canopy of this blacksmith shop are missing. Rebuild the visible furnace basin with its rim and recessed working area, the bellows beside it, the anvil with horn and waist, its supporting stand and fixing details, and the two small heated iron pieces shown in input/reference.png. Preserve the working clearances between these objects. Match the neutral clay-like presentation and the small warm forge accents in the supplied reference; do not add a new texture style. Leave the building, canopy, hanging tools, barrels, stairs and all other surviving geometry unchanged.',
 zh='铁匠铺侧边雨棚下的炉台、风箱和铁砧组件缺失。按 input/reference.png 补回炉台边沿与凹入工作区、旁侧风箱、带尖角和收腰的铁砧、下方支座及固定细节，以及图中的两件小型热铁。保留设备之间的操作空间。匹配参考中的中性灰模表现及少量暖色炉火点缀，不另加一种贴图风格。建筑、雨棚、悬挂工具、桶、台阶及其余保留几何不变。', features='炉台凹腔；风箱；铁砧尖角及收腰；支座固定；操作净空'),
 dict(key='frosty-cyberpunk', old='SceneEdit-AutumnPalette', slug='SceneEdit-NeonSigns', category='SceneEdit', title='科幻走廊：补回两处霓虹轮廓灯', difficulty='medium', mode='geometry', remove=['Light_Neon_Duck.001','Light_Neon_Suzanne'],
 en='Two luminous outline signs are missing from the corridor: the large duck outline on the near left wall and the smaller animal-face outline farther down the passage. Rebuild their continuous tubular curves, open interior spaces and distinct colored segments to match input/reference.png. Use the walls and remaining trim lights to recover placement, thickness and relative scale. Recreate their surface emission so that they illuminate nearby surfaces naturally; do not add separate lights to imitate the glow. Preserve the corridor, pipes, cables, screens, furniture, all existing lights and camera settings. Only the missing sign geometry and its materials may be added.',
 zh='走廊中缺少两处发光轮廓标识：近处左墙的大鸭子轮廓，以及通道更深处较小的动物脸轮廓。按 input/reference.png 补回连续管状曲线、内部空隙及不同色段，结合墙面和保留灯带恢复位置、粗细和相对尺寸。通过标识表面自发光自然照亮附近表面，不另加灯光伪造光晕。走廊、管道、线缆、屏幕、家具、现有灯和相机设置不变；只添加缺失标识几何及其材质。', features='连续曲线灯管；内部镂空；多色段；自发光及局部反射；其余场景保持'),
 dict(key='space-hallways', old='SceneEdit', slug='SceneEdit-CorridorCargo', category='SceneEdit', title='飞船通道：补回覆布货桶组', difficulty='medium', mode='geometry', remove=['Cylinder','Cylinder.001','Cylinder.002','cloth'],
 en='The near cargo group on the right side of the spaceship corridor has been removed. Restore the three compact cylindrical containers and the cloth draped over them as shown in input/reference.png. Recreate the rims, side bands and visible openings or caps, preserve the staggered arrangement, and give the cloth thickness and folds that follow its support. Keep the center walkway open, ground each barrel and avoid cloth intersecting its supporting containers. Match the metal and fabric appearance under the existing lighting. Leave the corridor panels, pipes, doors, remaining distant barrels, atmosphere and lighting unchanged.',
 zh='飞船走廊近处右侧的货物组已被移除。按 input/reference.png 补回三只紧凑圆桶及覆盖其上的布料，恢复桶沿、侧面箍带及可见开口或盖，保持错落排列，布料具有厚度和随支撑起伏的褶皱。中央通道保持畅通，每只桶落地，布料不穿入支撑桶体。匹配现有照明下的金属和布面。走廊面板、管线、舱门、远处保留桶、气氛和灯光均不变。', features='三桶错落；桶沿箍带；覆布厚度及褶皱；接触关系；中央通道'),
 dict(key='medieval-dungeon-interior', old='SceneEdit-PedestalTable', slug='SceneEdit-VaultLighting', category='SceneEdit', title='石砌地牢：恢复拱道照明', difficulty='easy', mode='lighting',
 en='The stone corridor geometry and materials are intact, but the existing lights have become too dim and blue. Restore the neutral, readable illumination shown in input/reference.png by changing only the colors and energies of existing lights. Recover the masonry relief around the main arch and the depth beyond it, without flattening the shadows. Keep light positions, directions, types and sizes fixed. Do not add lights, modify materials or geometry, change the world, alter exposure or use compositor corrections.',
 zh='石砌走廊的几何和材质完整，但已有灯变得过暗且偏蓝。只调整已有灯的颜色与能量，恢复 input/reference.png 中中性、清晰的照明，让主拱周围砖石起伏和后方纵深可读，同时保留阴影。灯位、朝向、类型和尺寸固定。不加灯、不改材质几何或世界环境，不调整曝光，也不用合成器校色。', features='拱道浮雕明暗；前后纵深；中性照明；灯位与几何材质保持'),
 dict(key='winter-castle', old='SceneEdit-HarborLighting', slug='SceneEdit-WinterSkyLight', category='SceneEdit', title='雪原骑士：恢复阴云日光层次', difficulty='hard', mode='lighting',
 en='The illumination of this snowy landscape has become excessively dim and blue. Restore the balance in input/reference.png: readable foreground rider and horse, textured snow, a softer distant fortress and mountains, and the bright breaks in the cloudy sky. Adjust only colors and energies of existing light objects and the existing world background strength. Keep the world texture and node connections, light positions, sizes and directions, all geometry and materials, volumetric settings, camera, saved frame, exposure and compositor unchanged. Do not add lights. Recover regional contrast and plausible cast shadows without clipping the snow or turning the rider into a uniformly bright silhouette.',
 zh='雪原照明变得过暗且偏蓝。恢复 input/reference.png 中的平衡：前景骑士和马可读、积雪有纹理、远处城堡与山脉更柔和、阴云间隙保留亮部。只调整已有灯的颜色与能量，以及已有世界背景强度。世界贴图及节点连线、灯位尺寸朝向、全部几何材质、体积设置、相机、保存帧、曝光与合成器均不变，不添加灯光。恢复分区反差与合理投影，避免雪面过曝或将骑士均匀提亮成平板剪影。', features='骑士马匹受光；雪面高光纹理；云隙与远山层次；区域对比；保持性'),
]
